import {calculate,validate,parseCSV,columns} from './payroll.js';
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format(n);
const sample=[['E101','Arun','Developer',30000,10000,3000,2000,24,5,50000],['E102','Meera','Tester',25000,8000,2500,1500,22,2,30000],['E103','John','Manager',40000,12000,4000,2000,26,0,60000]].map(r=>Object.fromEntries(columns.map((c,i)=>[c,r[i]])));
let employees=sample, javaConnected=false, editing=null, activeSlip=null, results=new Map(), revision=0;
try{const saved=JSON.parse(localStorage.getItem('micro-payroll-employees-v1'));if(Array.isArray(saved)&&saved.every(e=>!validate(e))&&new Set(saved.map(e=>e.employeeId)).size===saved.length) employees=saved;}catch{}
const now=new Date();$('#period').value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
const period=()=>new Date($('#period').value+'-01T12:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function save(){try{localStorage.setItem('micro-payroll-employees-v1',JSON.stringify(employees));}catch{toast('Browser storage unavailable. Export your records before closing.');}}
function get(e){return results.get(e.employeeId)||calculate(e)}
async function refresh(){const current=++revision;results.clear();render();if(!javaConnected)return;try{const pairs=await Promise.all(employees.map(async e=>{const response=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(e)});if(!response.ok)throw Error('Java calculation failed');return[e.employeeId,await response.json()]}));if(current!==revision)return;results=new Map(pairs);render();}catch{if(current!==revision)return;javaConnected=false;setConnection();toast('Java server unavailable. Using equivalent browser calculations.');}}
function render(){let totals={gross:0,pf:0,professionalTax:0,monthlyTDS:0,net:0};for(const e of employees){const c=get(e);for(const k in totals)totals[k]+=c[k];}const deductions=totals.pf+totals.professionalTax+totals.monthlyTDS;
$('#total-employees').textContent=employees.length;$('#nav-count').textContent=employees.length;$('#table-count').textContent=employees.length;$('#total-gross').textContent=money(totals.gross);$('#total-deductions').textContent=money(deductions);$('#total-net').textContent=money(totals.net);$('#donut-total').textContent=money(totals.gross);
const parts=[['Take-home pay',totals.net,'#4e8061'],['Provident fund',totals.pf,'#a0b89c'],['Income tax / TDS',totals.monthlyTDS,'#d0dcc4'],['Professional tax',totals.professionalTax,'#e7eae1']];let cumulative=0;const stops=parts.map(([,v,color])=>{const start=cumulative;cumulative+=totals.gross?v/totals.gross*100:0;return `${color} ${start}% ${cumulative}%`;});$('#donut').style.background=totals.gross?`conic-gradient(${stops.join(',')})`:'#e8edeb';$('#legend').innerHTML=parts.map(([name,value,color])=>`<div class="legend-row"><span><i style="background:${color}"></i>${name}</span><strong>${money(value)}</strong></div>`).join('');
const query=$('#search').value.toLowerCase();const filtered=employees.filter(e=>`${e.name} ${e.employeeId} ${e.designation}`.toLowerCase().includes(query));
$('#employee-rows').innerHTML=filtered.length?filtered.map(e=>{const c=get(e);return `<tr><td><div class="employee-cell"><span class="avatar">${escape(e.name.split(/\s+/).map(n=>n[0]).slice(0,2).join('').toUpperCase())}</span><div><div class="employee-name">${escape(e.name)}</div><div class="employee-meta">${escape(e.employeeId)} · ${escape(e.designation)}</div></div></div></td><td>${money(e.basicPay)}</td><td>${money(c.gross)}</td><td>${money(c.gross-c.net)}</td><td class="net">${money(c.net)}</td><td><button class="view-slip" data-slip="${escape(e.employeeId)}">View payslip ↗</button></td><td><button class="edit-button" data-edit="${escape(e.employeeId)}" aria-label="Edit ${escape(e.name)}">Edit</button><button class="edit-button" data-delete="${escape(e.employeeId)}" aria-label="Delete ${escape(e.name)}">×</button></td></tr>`}).join(''):'<tr><td colspan="7" class="empty">'+(employees.length?'No employees match your search.':'Your team starts here. Add an employee or import a CSV.')+'</td></tr>';
$('#showing').textContent=`Showing ${filtered.length} of ${employees.length} employees`;}
function setConnection(){$('#connection').textContent=javaConnected?'● Java backend connected':'● Browser demo';$('#demo-note').innerHTML=`<span class="note-icon">i</span><span><strong>${javaConnected?'Java workspace':'Demo workspace'}</strong> · ${javaConnected?'Calculations use your original Java classes.':'Sample data · Calculations run in your browser.'} Employee records stay in this browser.</span><button id="import-top">Import CSV ↗</button>`;$('#import-top').onclick=()=>$('#csv-input').click();}
function openForm(id){editing=id||null;const e=employees.find(e=>e.employeeId===id);$('#employee-form').reset();$('#form-error').textContent='';$('#form-title').textContent=e?'Edit employee':'Add employee';for(const c of columns){const field=$('#employee-form').elements[c];field.value=e?e[c]:(c==='workingDays'?26:columns.indexOf(c)>2?0:'');}$('#employee-dialog').showModal();}
$('#add-employee').onclick=()=>openForm();
$('#employee-form').onsubmit=async event=>{event.preventDefault();const employee=Object.fromEntries(new FormData(event.target));columns.slice(3).forEach(k=>employee[k]=Number(employee[k]));columns.slice(0,3).forEach(k=>employee[k]=employee[k].trim());const error=validate(employee);if(error){$('#form-error').textContent=error;return;}if(employees.some(e=>e.employeeId===employee.employeeId&&e.employeeId!==editing)){$('#form-error').textContent='This employee ID already exists.';return;}if(editing)employees=employees.map(e=>e.employeeId===editing?employee:e);else employees.push(employee);save();$('#employee-dialog').close();await refresh();toast(editing?'Employee updated.':'Employee added.');};
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#employee-rows').onclick=event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.edit)openForm(b.dataset.edit);if(b.dataset.slip)openSlip(b.dataset.slip);if(b.dataset.delete){const e=employees.find(e=>e.employeeId===b.dataset.delete);if(confirm(`Delete ${e.name} (${e.employeeId}) from this browser workspace?`)){employees=employees.filter(x=>x!==e);save();refresh();toast('Employee deleted.');}}};
function openSlip(id){activeSlip=employees.find(e=>e.employeeId===id);const e=activeSlip,c=get(e);$('#slip-name').textContent=e.name;$('#slip-meta').textContent=`${e.employeeId} · ${e.designation} · ${period()}`;const row=(label,value)=>`<div class="slip-row"><span>${label}</span><strong>${money(value)}</strong></div>`;$('#slip-content').innerHTML='<div class="slip-section">EARNINGS</div>'+[['Basic pay',e.basicPay],['House rent allowance',e.hra],['Dearness allowance',e.da],['Conveyance',e.conveyance],['Gross salary',c.gross]].map(([l,v])=>row(l,v)).join('')+'<div class="slip-section">DEDUCTIONS</div>'+[['Provident fund (12% of basic)',c.pf],['Professional tax',c.professionalTax],['Monthly TDS',c.monthlyTDS]].map(([l,v])=>row(l,v)).join('')+`<div class="slip-row slip-total"><span>Take-home pay</span><span>${money(c.net)}</span></div>`+'<div class="slip-section">ANNUAL TAX DETAILS</div>'+[['Annual gross income',c.annualIncome],['Taxable income',c.taxableIncome],['Illustrative annual tax',c.annualTax]].map(([l,v])=>row(l,v)).join('')+`<p class="form-note">Working days: ${e.workingDays} · Overtime hours: ${e.overtimeHours}<br>Illustrative rules from the Java project. This is a payroll calculation, not a payment confirmation.</p>`;$('#payslip-dialog').showModal();}
function download(filename,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#download-slip').onclick=()=>{const e=activeSlip,c=get(e);download(`payslip_${e.employeeId.replace(/[^a-zA-Z0-9_-]/g,'_')}_${$('#period').value}.txt`,['MICRO PAYROLL — EMPLOYEE PAYSLIP',period(),`${e.name} | ${e.employeeId} | ${e.designation}`,'',...columns.slice(3).map(k=>`${k}: ${e[k]}`),'',...Object.entries(c).map(([k,v])=>`${k}: INR ${v.toFixed(2)}`),'','Illustrative payroll calculation. No payment has been made.'].join('\n'));toast('Payslip downloaded.');};
$('#search').oninput=render;$('#period').onchange=()=>{if(!$('#period').value){$('#period').value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;}toast(`Payslips will be labeled ${period()}. Salary inputs are shared across periods.`);};
$('#guide').onclick=()=>$('#guide-dialog').showModal();$('#review-payroll').onclick=()=>location.hash='payroll';
$('#export-button').onclick=()=>{if(!employees.length){toast('Add employees before exporting a summary.');return;}const csvEscape=v=>{const text=String(v);return '"'+(/^[=+@\-\t\r]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"'};const header=[...columns,'gross','pf','professionalTax','monthlyTDS','net'];const rows=employees.map(e=>{const c=get(e);return header.map(k=>csvEscape(e[k]??c[k])).join(',')});download(`payroll_summary_${$('#period').value}.csv`,[header.join(','),...rows].join('\r\n'),'text/csv;charset=utf-8');toast('Payroll summary exported.');};
$('#import-button').onclick=()=>$('#csv-input').click();$('#import-top').onclick=()=>$('#csv-input').click();
$('#csv-input').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Please use a CSV smaller than 2 MB.');const parsed=parseCSV(await file.text());const seen=new Set(employees.map(e=>e.employeeId));let added=0,skipped=0;for(const e of parsed){if(validate(e)||seen.has(e.employeeId)){skipped++;continue;}seen.add(e.employeeId);employees.push(e);added++;}save();await refresh();toast(`Imported ${added} employee${added===1?'':'s'}.${skipped?` Skipped ${skipped} invalid or duplicate row(s).`:''}`);}catch(error){toast(error.message);}event.target.value='';};
function route(){const page=['overview','employees','payroll','payslips'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';const labels={overview:['Overview','Payroll, at a glance','A clear view of your team’s monthly payroll. All in one place.'],employees:['Employees','Good people. Great team','Manage employee details and salary components in one place.'],payroll:['Payroll','Make payday a good day','Review your team’s calculated salary and monthly deductions.'],payslips:['Payslips','Every detail, accounted for','View and download individual employee payslips.']};$('#crumb').textContent=labels[page][0];$('#page-title').textContent=labels[page][1]+'.';$('#page-description').textContent=labels[page][2];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#overview-content').hidden=page!=='overview';$('#table-title').textContent=page==='employees'?'Your employees':page==='payslips'?'Employee payslips':'Employee payroll';}
window.addEventListener('hashchange',route);route();render();
try{const response=await fetch('/api/health',{signal:AbortSignal.timeout(3000)});if(response.ok){const health=await response.json();javaConnected=health.engine==='java';}}catch{}setConnection();await refresh();
